import{_ as t,o,c as a,ag as r}from"./chunks/framework.DNmTgtHf.js";const p=JSON.parse('{"title":"DNS — Resolution Flow, Caching, and Traffic Steering","description":"","frontmatter":{},"headers":[],"relativePath":"networking/dns/DnsResolution.md","filePath":"networking/dns/DnsResolution.md"}'),s={name:"networking/dns/DnsResolution.md"};function n(i,e,l,d,c,h){return o(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="dns-—-resolution-flow-caching-and-traffic-steering" tabindex="-1">DNS — Resolution Flow, Caching, and Traffic Steering <a class="header-anchor" href="#dns-—-resolution-flow-caching-and-traffic-steering" aria-label="Permalink to &quot;DNS — Resolution Flow, Caching, and Traffic Steering&quot;">​</a></h1><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><h3 id="what-dns-does-—-and-does-not-do" tabindex="-1">What DNS does — and does NOT do <a class="header-anchor" href="#what-dns-does-—-and-does-not-do" aria-label="Permalink to &quot;What DNS does — and does NOT do&quot;">​</a></h3><p>DNS converts human-readable domain names into IP addresses (<code>google.com</code> → <code>142.250.x.x</code>). DNS resolution only answers <em>&quot;what IP address should I connect to?&quot;</em> It does <strong>not</strong> send the webpage, establish TCP connections, perform TLS handshakes, or serve application data — all of that happens <em>after</em> DNS resolution completes:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DNS → TCP → TLS → HTTP</span></span></code></pre></div><p>(Why DNS runs over UDP is covered in <code>networking/tcp_vs_udp/TcpVsUdp.md</code>.)</p><h3 id="the-players" tabindex="-1">The players <a class="header-anchor" href="#the-players" aria-label="Permalink to &quot;The players&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Player</th><th>Role</th></tr></thead><tbody><tr><td><strong>Client</strong></td><td>The user&#39;s machine/browser — needs an IP before it can connect</td></tr><tr><td><strong>DNS resolver (recursive resolver)</strong></td><td>Performs the whole lookup <em>on behalf of</em> the client. Examples: Google DNS <code>8.8.8.8</code>, Cloudflare <code>1.1.1.1</code>, ISP DNS. The client never directly contacts root/TLD/authoritative servers</td></tr><tr><td><strong>Root server</strong></td><td>Does NOT know website IPs. Only knows where the TLD servers are (&quot;ask the <code>.com</code> servers&quot;)</td></tr><tr><td><strong>TLD server</strong> (<code>.com</code>, <code>.org</code>, <code>.net</code>, <code>.in</code>, <code>.io</code>)</td><td>Does NOT know the final IP either. Knows which authoritative server owns the domain (&quot;ask Google&#39;s DNS&quot;)</td></tr><tr><td><strong>Authoritative server</strong></td><td>The final source of truth — holds the actual DNS records and returns the IP</td></tr></tbody></table><h3 id="the-hierarchy" tabindex="-1">The hierarchy <a class="header-anchor" href="#the-hierarchy" aria-label="Permalink to &quot;The hierarchy&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Root</span></span>
<span class="line"><span> ├── .com ── google.com ── actual DNS records</span></span>
<span class="line"><span> ├── .org          amazon.com</span></span>
<span class="line"><span> ├── .net          netflix.com</span></span>
<span class="line"><span> └── .in</span></span></code></pre></div><p>The hierarchy exists so that <strong>no single server needs to store information about every domain on Earth.</strong></p><h3 id="complete-resolution-flow-nothing-cached" tabindex="-1">Complete resolution flow (nothing cached) <a class="header-anchor" href="#complete-resolution-flow-nothing-cached" aria-label="Permalink to &quot;Complete resolution flow (nothing cached)&quot;">​</a></h3><ol><li><strong>Browser cache</strong> — &quot;do I already know google.com&#39;s IP?&quot; If yes, lookup ends here.</li><li><strong>OS DNS cache</strong> — if found, lookup ends.</li><li><strong>Browser asks the resolver</strong> — resolver doesn&#39;t know yet.</li><li><strong>Resolver asks a root server</strong> → &quot;ask the <code>.com</code> TLD servers.&quot; (No IP yet.)</li><li><strong>Resolver asks the <code>.com</code> TLD server</strong> → &quot;ask Google&#39;s authoritative server.&quot; (Still no IP.)</li><li><strong>Resolver asks the authoritative server</strong> → <code>142.250.x.x</code> — the actual record.</li><li><strong>Resolver returns the IP to the client</strong> and caches it. Only now does the browser start TCP → TLS → HTTP.</li></ol><h3 id="caching-and-ttl" tabindex="-1">Caching and TTL <a class="header-anchor" href="#caching-and-ttl" aria-label="Permalink to &quot;Caching and TTL&quot;">​</a></h3><p>Without caching every lookup would walk resolver → root → TLD → authoritative — slow and expensive. DNS caches at multiple layers: <strong>browser → OS → resolver</strong>. Because of this, most lookups never reach root servers.</p><p><strong>TTL (Time To Live)</strong> defines how long a DNS answer may be cached. <code>TTL = 300</code> means &quot;cache for 5 minutes, then ask again.&quot;</p><p><strong>Why TTL exists:</strong> if the IP behind a domain changes (<code>142.250.195.78</code> → <code>142.250.195.90</code>) and clients cached forever, traffic would keep hitting the old server. TTL prevents stale routing.</p><p><strong>TTL trade-off:</strong></p><table tabindex="0"><thead><tr><th>High TTL</th><th>Low TTL</th></tr></thead><tbody><tr><td>Fewer DNS queries</td><td>More DNS queries</td></tr><tr><td>Better cache hit rate</td><td>Lower cache hit rate</td></tr><tr><td>Lower DNS load</td><td>Higher DNS load</td></tr><tr><td>Slower failover</td><td>Faster failover</td></tr><tr><td>Slower migrations</td><td>Faster migrations</td></tr></tbody></table><p>Common interview point: <strong>before a migration or failover, teams reduce TTL</strong> so caches expire quickly and traffic moves to the new destination faster.</p><h3 id="dns-based-traffic-steering" tabindex="-1">DNS-based traffic steering <a class="header-anchor" href="#dns-based-traffic-steering" aria-label="Permalink to &quot;DNS-based traffic steering&quot;">​</a></h3><p>DNS is not only name resolution — large systems use it to decide <em>where</em> traffic should go. The same domain can return different IPs: a user in Bangalore gets a Bangalore IP for <code>netflix.com</code>, a user in London gets a London IP.</p><p><strong>CDNs:</strong> with servers in Bangalore, Singapore, Tokyo, London, New York, the authoritative DNS returns different IPs depending on user location — routing users to nearby infrastructure. DNS becomes the first layer of load balancing.</p><p><strong>DNS-based load balancing:</strong> the authoritative server can return Server A, B, or C based on geography, latency, traffic conditions, or health checks. DNS is a traffic-control mechanism, not just a phonebook.</p><p><strong>DNS-based failover:</strong> if a server becomes unavailable, DNS can be updated to return a backup server&#39;s IP.</p><h3 id="how-dns-determines-user-location-—-important-nuance" tabindex="-1">How DNS determines user location — important nuance <a class="header-anchor" href="#how-dns-determines-user-location-—-important-nuance" aria-label="Permalink to &quot;How DNS determines user location — important nuance&quot;">​</a></h3><p>The authoritative DNS server often sees the <strong>resolver&#39;s IP address, not the end user&#39;s IP</strong>. If you use Cloudflare&#39;s resolver, Netflix&#39;s DNS primarily sees the Cloudflare resolver IP, not your exact IP. This is one reason DNS-based geolocation is approximate.</p><h2 id="gotchas-trick-questions" tabindex="-1">Gotchas / Trick questions <a class="header-anchor" href="#gotchas-trick-questions" aria-label="Permalink to &quot;Gotchas / Trick questions&quot;">​</a></h2><ol><li><strong>&quot;Root servers know website IPs.&quot;</strong> No — they only know <code>TLD → TLD server locations</code> (<code>.com → TLD servers</code>). They are the first directory lookup.</li><li><strong>&quot;TLD servers know website IPs.&quot;</strong> No — they only know <code>google.com → authoritative server</code>. The authoritative server holds the actual records.</li><li><strong>&quot;DNS lookup sends webpage data.&quot;</strong> No — DNS only provides domain → IP. The webpage is fetched afterwards via TCP → TLS → HTTP.</li><li><strong>&quot;Every website must run its own authoritative DNS servers.&quot;</strong> Not necessarily. Every domain must <em>have</em> authoritative servers, but a DNS provider may run them on the company&#39;s behalf — ownership and operation are separate concerns.</li><li><strong>&quot;Root servers seem unnecessary — why not let resolvers know all TLD servers directly?&quot;</strong> The root layer is a universal, globally consistent starting point. Without it, every resolver would independently maintain the TLD mapping.</li><li><strong>&quot;Root servers must be overloaded since every lookup starts there.&quot;</strong> Not in practice — resolvers cache TLD information, authoritative information, and final records for long periods, so most lookups never reach the root.</li><li><strong>Do root and TLD servers have fixed IPs?</strong> Yes — resolvers rely on stable root-server information, and TLD servers also keep stable addresses.</li><li><strong>Where are root-server addresses stored?</strong> Not in browsers — resolvers ship with a <strong>root-hints file</strong> containing root-server information.</li></ol><h2 id="performance-characteristics" tabindex="-1">Performance characteristics <a class="header-anchor" href="#performance-characteristics" aria-label="Permalink to &quot;Performance characteristics&quot;">​</a></h2><h3 id="why-dns-scales" tabindex="-1">Why DNS scales <a class="header-anchor" href="#why-dns-scales" aria-label="Permalink to &quot;Why DNS scales&quot;">​</a></h3><p>The hierarchy distributes responsibility — no layer stores the entire internet:</p><table tabindex="0"><thead><tr><th>Layer</th><th>Responsibility</th></tr></thead><tbody><tr><td>Root</td><td>Knows TLD locations</td></tr><tr><td>TLD</td><td>Knows authoritative servers</td></tr><tr><td>Authoritative</td><td>Knows actual records</td></tr></tbody></table><h3 id="why-caching-is-critical" tabindex="-1">Why caching is critical <a class="header-anchor" href="#why-caching-is-critical" aria-label="Permalink to &quot;Why caching is critical&quot;">​</a></h3><p>Without caching: every lookup → root → TLD → authoritative. With caching: most lookups end at a resolver cache hit — dramatically lower latency and infrastructure load.</p><h2 id="good-to-know" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know" aria-label="Permalink to &quot;Good to know&quot;">​</a></h2><h3 id="mental-model" tabindex="-1">Mental model <a class="header-anchor" href="#mental-model" aria-label="Permalink to &quot;Mental model&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Root          → Reception desk  (&quot;ask .com&quot;)</span></span>
<span class="line"><span>TLD           → Department      (&quot;ask Google&#39;s DNS&quot;)</span></span>
<span class="line"><span>Authoritative → Actual owner    (&quot;here is the IP&quot;)</span></span></code></pre></div><p>This single mental model is often enough to reconstruct the entire DNS lookup process during interviews.</p><h3 id="dns-is-more-than-a-phonebook" tabindex="-1">DNS is more than a phonebook <a class="header-anchor" href="#dns-is-more-than-a-phonebook" aria-label="Permalink to &quot;DNS is more than a phonebook&quot;">​</a></h3><p>Beyond name → IP mapping, DNS participates in CDN routing, traffic steering, load balancing, and failover — which is why it appears constantly in system design discussions.</p><h2 id="quick-recall" tabindex="-1">Quick recall <a class="header-anchor" href="#quick-recall" aria-label="Permalink to &quot;Quick recall&quot;">​</a></h2><p><strong>Q. What is the job of a DNS resolver?</strong> A. Find the IP on behalf of the client by querying root, TLD, and authoritative servers.</p><p><strong>Q. Does a root server know google.com&#39;s IP? Does a TLD server?</strong> A. No and no. Root knows where <code>.com</code> TLD servers are; TLD knows which authoritative server owns google.com.</p><p><strong>Q. Which server holds the final DNS records?</strong> A. The authoritative DNS server.</p><p><strong>Q. What does TTL control?</strong> A. How long DNS responses may be cached before revalidation.</p><p><strong>Q. Why reduce TTL before a migration?</strong> A. So cached records expire quickly and traffic moves to the new destination faster.</p><p><strong>Q. Does DNS send webpage data?</strong> A. No — DNS only resolves names to IPs; TCP/TLS/HTTP happen afterward.</p><p><strong>Q. How do CDNs use DNS?</strong> A. They return different IPs by user location/conditions, steering users to nearby infrastructure — though geolocation is approximate because the authoritative server usually sees the resolver&#39;s IP, not the user&#39;s.</p><p><strong>Q. How does DNS provide load balancing and failover?</strong> A. Different IPs for the same domain (by geography, latency, health), and record updates that point traffic at backup servers.</p>`,50)])])}const g=t(s,[["render",n]]);export{p as __pageData,g as default};
